#define _GNU_SOURCE
#include "pocketpc_display_bridge.h"
#include <errno.h>
#include <stddef.h>
#include <poll.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <sys/time.h>
#include <sys/un.h>
#include <unistd.h>
#define PDB_SOCKET_TIMEOUT_SECONDS 5
#define PDB_POINTER_BUTTON_ALLOWED (PDB_POINTER_BUTTON_PRIMARY|PDB_POINTER_BUTTON_SECONDARY|PDB_POINTER_BUTTON_MIDDLE)
#define PDB_MODIFIER_ALLOWED_LOCAL PDB_MODIFIER_ALLOWED

static void set_error(char*e,size_t n,const char*m){if(e&&n)snprintf(e,n,"%s",m?m:"PDB_ERROR");}
static void p16(unsigned char*p,uint16_t v){p[0]=v;p[1]=v>>8;} static void p32(unsigned char*p,uint32_t v){int i;for(i=0;i<4;i++)p[i]=v>>(8*i);} static void p64(unsigned char*p,uint64_t v){int i;for(i=0;i<8;i++)p[i]=v>>(8*i);}
static uint16_t g16(const unsigned char*p){return p[0]|((uint16_t)p[1]<<8);} static uint32_t g32(const unsigned char*p){return p[0]|((uint32_t)p[1]<<8)|((uint32_t)p[2]<<16)|((uint32_t)p[3]<<24);} static uint64_t g64(const unsigned char*p){uint64_t v=0;int i;for(i=0;i<8;i++)v|=((uint64_t)p[i])<<(8*i);return v;}
static int nib(char c){if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;if(c>='A'&&c<='F')return c-'A'+10;return-1;}
static int token(const char*t,unsigned char*out){size_t i;if(!t||strlen(t)!=64)return-1;for(i=0;i<32;i++){int h=nib(t[2*i]),l=nib(t[2*i+1]);if(h<0||l<0)return-1;out[i]=(h<<4)|l;}return 0;}
static int identity_ok(const char*s){size_t i;if(!s||strlen(s)!=64)return 0;for(i=0;i<64;i++)if(!((s[i]>='0'&&s[i]<='9')||(s[i]>='a'&&s[i]<='f')))return 0;return 1;}
static void hex16(const unsigned char*in,char*out){static const char*h="0123456789abcdef";size_t i;for(i=0;i<16;i++){out[i*2]=h[in[i]>>4];out[i*2+1]=h[in[i]&15];}out[32]=0;}
static int cap(struct pdb_connection*c,uint32_t bit,char*e,size_t n){if(!c||!(c->negotiated_capabilities&bit)){set_error(e,n,"PDB_CAPABILITY_NOT_NEGOTIATED");return 0;}return 1;}
static void invalidate_connection(struct pdb_connection*c){if(!c)return;if(c->fd>=0)close(c->fd);c->fd=-1;c->negotiated_capabilities=0;c->next_sequence=0;c->expected_inbound_sequence=0;}
static int wall(int fd,const unsigned char*d,size_t n){size_t o=0;while(o<n){ssize_t w=write(fd,d+o,n-o);if(w<0){if(errno==EINTR)continue;return-1;}if(!w)return-1;o+=w;}return 0;}
static int rall(int fd,unsigned char*d,size_t n){size_t o=0;while(o<n){ssize_t r=read(fd,d+o,n-o);if(r<0){if(errno==EINTR)continue;return-1;}if(!r)return-1;o+=r;}return 0;}
static int rawsend(int fd,uint16_t type,uint64_t seq,const void*payload,uint32_t n){unsigned char h[20];if(n>PDB_MAX_PAYLOAD_BYTES)return-1;p32(h,PDB_MAGIC);p16(h+4,PDB_VERSION);p16(h+6,type);p32(h+8,n);p64(h+12,seq);return wall(fd,h,20)||(n&&wall(fd,payload,n))?-1:0;}
static int rawrecv(int fd,struct pdb_frame*f){unsigned char h[20];if(!f||rall(fd,h,20)||g32(h)!=PDB_MAGIC||g16(h+4)!=PDB_VERSION)return-1;memset(f,0,sizeof(*f));f->type=g16(h+6);f->payload_bytes=g32(h+8);f->sequence=g64(h+12);if(f->payload_bytes>PDB_MAX_PAYLOAD_BYTES)return-1;if(f->payload_bytes){f->payload=malloc(f->payload_bytes);if(!f->payload||rall(fd,f->payload,f->payload_bytes)){free(f->payload);memset(f,0,sizeof(*f));return-1;}}return 0;}
int pdb_connect_from_environment(struct pdb_connection*c,char*e,size_t n){const char*pr=getenv("POCKETPC_DISPLAY_PROTOCOL"),*sn=getenv("POCKETPC_DISPLAY_SOCKET"),*th=getenv("POCKETPC_DISPLAY_TOKEN"),*id=getenv("POCKETPC_DISPLAY_RUNTIME_SHA256"),*ct=getenv("POCKETPC_DISPLAY_HOST_CAPS");unsigned char tk[32],hello[100];struct sockaddr_un a;struct pdb_frame ack;char*end=0;unsigned long caps;size_t nl;int fd;if(!c||!pr||strcmp(pr,"3")||!sn||!identity_ok(id)||token(th,tk)){set_error(e,n,"PDB_ENV_INVALID");return-1;}errno=0;caps=strtoul(ct?ct:"",&end,10);if(errno||!ct||!end||*end||caps>0xfffffffful){set_error(e,n,"PDB_CAPABILITIES_INVALID");return-1;}nl=strlen(sn);if(!nl||nl>sizeof(a.sun_path)-2){set_error(e,n,"PDB_SOCKET_NAME_INVALID");return-1;}fd=socket(AF_UNIX,SOCK_STREAM|SOCK_CLOEXEC,0);if(fd<0){set_error(e,n,"PDB_SOCKET_CREATE_FAILED");return-1;}{struct timeval timeout;memset(&timeout,0,sizeof(timeout));timeout.tv_sec=PDB_SOCKET_TIMEOUT_SECONDS;if(setsockopt(fd,SOL_SOCKET,SO_RCVTIMEO,&timeout,sizeof(timeout))!=0||setsockopt(fd,SOL_SOCKET,SO_SNDTIMEO,&timeout,sizeof(timeout))!=0){close(fd);set_error(e,n,"PDB_SOCKET_TIMEOUT_SETUP_FAILED");return-1;}}memset(&a,0,sizeof(a));a.sun_family=AF_UNIX;a.sun_path[0]=0;memcpy(a.sun_path+1,sn,nl);if(connect(fd,(struct sockaddr*)&a,(socklen_t)(offsetof(struct sockaddr_un,sun_path)+1+nl))){close(fd);set_error(e,n,"PDB_CONNECT_FAILED");return-1;}memcpy(hello,tk,32);memcpy(hello+32,id,64);p32(hello+96,(uint32_t)caps);if(rawsend(fd,PDB_MSG_HELLO,0,hello,100)||rawrecv(fd,&ack)){close(fd);set_error(e,n,"PDB_HANDSHAKE_FAILED");return-1;}if(ack.type!=PDB_MSG_HELLO_ACK||ack.sequence||ack.payload_bytes!=4){pdb_release_frame(&ack);close(fd);set_error(e,n,"PDB_HELLO_ACK_INVALID");return-1;}c->negotiated_capabilities=g32(ack.payload);pdb_release_frame(&ack);if((c->negotiated_capabilities&(uint32_t)caps)!=c->negotiated_capabilities){close(fd);set_error(e,n,"PDB_HELLO_ACK_CAPS_INVALID");return-1;}c->fd=fd;c->next_sequence=1;c->expected_inbound_sequence=1;return 0;}
int pdb_send_frame(struct pdb_connection*c,uint16_t t,const void*p,uint32_t b,char*e,size_t n){uint64_t s;if(!c||c->fd<0||b>PDB_MAX_PAYLOAD_BYTES||(b&&!p)){set_error(e,n,"PDB_SEND_ARGUMENT_INVALID");return-1;}s=c->next_sequence;if(!s){invalidate_connection(c);set_error(e,n,"PDB_SEQUENCE_EXHAUSTED");return-1;}if(rawsend(c->fd,t,s,p,b)){invalidate_connection(c);set_error(e,n,"PDB_SEND_FAILED");return-1;}c->next_sequence=(s==UINT64_MAX)?0u:s+1u;return 0;}
int pdb_receive_frame(struct pdb_connection*c,struct pdb_frame*f,char*e,size_t n){uint64_t expected;if(!c||c->fd<0||!f){set_error(e,n,"PDB_RECEIVE_ARGUMENT_INVALID");return-1;}expected=c->expected_inbound_sequence;if(!expected){invalidate_connection(c);set_error(e,n,"PDB_SEQUENCE_EXHAUSTED");return-1;}if(rawrecv(c->fd,f)){invalidate_connection(c);set_error(e,n,"PDB_RECEIVE_FAILED");return-1;}if(f->sequence!=expected){pdb_release_frame(f);invalidate_connection(c);set_error(e,n,"PDB_SEQUENCE_INVALID");return-1;}c->expected_inbound_sequence=(expected==UINT64_MAX)?0u:expected+1u;return 0;}
int pdb_connection_has_input(struct pdb_connection*c,char*e,size_t n){struct pollfd pfd;int rc;if(!c||c->fd<0){set_error(e,n,"PDB_POLL_ARGUMENT_INVALID");return-1;}memset(&pfd,0,sizeof(pfd));pfd.fd=c->fd;pfd.events=POLLIN;do{rc=poll(&pfd,1,0);}while(rc<0&&errno==EINTR);if(rc<0){set_error(e,n,"PDB_POLL_FAILED");return-1;}if(rc==0)return 0;if(pfd.revents&(POLLERR|POLLHUP|POLLNVAL)){set_error(e,n,"PDB_POLL_TERMINAL");return-1;}return (pfd.revents&POLLIN)?1:0;}

int pdb_send_surface_request(struct pdb_connection*c,const struct pdb_surface_request*v,char*e,size_t n){unsigned char p[PDB_SURFACE_REQUEST_BYTES];if(!v||!cap(c,PDB_CAP_WINDOW_SURFACE,e,n)||!v->window_id||!v->generation||v->width<=0||v->width>16384||v->height<=0||v->height>16384||v->pixel_format!=1u||v->flags!=0u){if(e&&n&&!e[0])set_error(e,n,"PDB_SURFACE_REQUEST_INVALID");return-1;}p64(p,v->window_id);p64(p+8,v->generation);p32(p+16,(uint32_t)v->width);p32(p+20,(uint32_t)v->height);p32(p+24,v->pixel_format);p32(p+28,v->flags);return pdb_send_frame(c,PDB_MSG_SURFACE_REQUEST,p,sizeof(p),e,n);}
int pdb_receive_surface_available(struct pdb_connection*c,struct pdb_surface_available*v,char*e,size_t n){struct pdb_frame f;if(!v||!cap(c,PDB_CAP_WINDOW_SURFACE,e,n)||pdb_receive_frame(c,&f,e,n))return-1;if(f.type!=PDB_MSG_SURFACE_AVAILABLE||f.payload_bytes!=PDB_SURFACE_AVAILABLE_BYTES){pdb_release_frame(&f);set_error(e,n,"PDB_SURFACE_FRAME_INVALID");return-1;}v->window_id=g64(f.payload);v->surface_id=g64(f.payload+8);v->generation=g64(f.payload+16);v->width=(int32_t)g32(f.payload+24);v->height=(int32_t)g32(f.payload+28);v->stride_bytes=(int32_t)g32(f.payload+32);v->pixel_format=g32(f.payload+36);hex16(f.payload+40,v->token_hex);pdb_release_frame(&f);if(!v->window_id||!v->surface_id||!v->generation||v->width<=0||v->width>16384||v->height<=0||v->height>16384||v->stride_bytes<v->width*4||v->stride_bytes>65536||v->pixel_format!=1){set_error(e,n,"PDB_SURFACE_PAYLOAD_INVALID");return-1;}return 0;}
int pdb_surface_guest_path(const struct pdb_surface_available*v,char*out,size_t n){int written;if(!v||!out||n==0||strlen(v->token_hex)!=32)return-1;written=snprintf(out,n,"/tmp/.pocketpc-surface-%s.bgra",v->token_hex);return written>0&&(size_t)written<n?0:-1;}
int pdb_send_frame_ready(struct pdb_connection*c,const struct pdb_frame_ready*v,char*e,size_t n){unsigned char p[PDB_FRAME_READY_BYTES];if(!v||!cap(c,PDB_CAP_WINDOW_SURFACE,e,n)||!v->window_id||!v->surface_id||!v->generation||!v->frame_id){if(e&&n&&!e[0])set_error(e,n,"PDB_FRAME_READY_INVALID");return-1;}p64(p,v->window_id);p64(p+8,v->surface_id);p64(p+16,v->generation);p64(p+24,v->frame_id);return pdb_send_frame(c,PDB_MSG_FRAME_READY,p,sizeof(p),e,n);}
int pdb_peek_message_type(struct pdb_connection*c,uint16_t*type,char*e,size_t n){unsigned char h[PDB_HEADER_BYTES];ssize_t got;if(!c||c->fd<0||!type){set_error(e,n,"PDB_PEEK_ARGUMENT_INVALID");return-1;}do{got=recv(c->fd,h,sizeof(h),MSG_PEEK|MSG_DONTWAIT);}while(got<0&&errno==EINTR);if(got<0){if(errno==EAGAIN||errno==EWOULDBLOCK)return 0;set_error(e,n,"PDB_PEEK_FAILED");return-1;}if(got==0){set_error(e,n,"PDB_PEEK_EOF");return-1;}if((size_t)got<sizeof(h))return 0;if(g32(h)!=PDB_MAGIC||g16(h+4)!=PDB_VERSION||g32(h+8)>PDB_MAX_PAYLOAD_BYTES){set_error(e,n,"PDB_PEEK_HEADER_INVALID");return-1;}*type=g16(h+6);return 1;}

int pdb_receive_host_event(struct pdb_connection*c,struct pdb_host_event*event,char*e,size_t n){struct pdb_frame f;if(!event){set_error(e,n,"PDB_HOST_EVENT_ARGUMENT_INVALID");return-1;}memset(event,0,sizeof(*event));if(pdb_receive_frame(c,&f,e,n))return-1;event->type=f.type;switch(f.type){case PDB_MSG_SURFACE_AVAILABLE:if(!cap(c,PDB_CAP_WINDOW_SURFACE,e,n)||f.payload_bytes!=PDB_SURFACE_AVAILABLE_BYTES){pdb_release_frame(&f);set_error(e,n,"PDB_SURFACE_FRAME_INVALID");return-1;}event->data.surface.window_id=g64(f.payload);event->data.surface.surface_id=g64(f.payload+8);event->data.surface.generation=g64(f.payload+16);event->data.surface.width=(int32_t)g32(f.payload+24);event->data.surface.height=(int32_t)g32(f.payload+28);event->data.surface.stride_bytes=(int32_t)g32(f.payload+32);event->data.surface.pixel_format=g32(f.payload+36);{size_t i;for(i=0;i<16;i++)snprintf(event->data.surface.token_hex+i*2,3,"%02x",f.payload[40+i]);event->data.surface.token_hex[32]='\0';}break;case PDB_MSG_POINTER_EVENT:if(!cap(c,PDB_CAP_POINTER,e,n)||f.payload_bytes!=PDB_POINTER_EVENT_BYTES){pdb_release_frame(&f);set_error(e,n,"PDB_POINTER_FRAME_INVALID");return-1;}event->data.pointer.window_id=g64(f.payload);event->data.pointer.action=g32(f.payload+8);event->data.pointer.x=(int32_t)g32(f.payload+12);event->data.pointer.y=(int32_t)g32(f.payload+16);event->data.pointer.buttons=g32(f.payload+20);event->data.pointer.vertical_scroll=(int32_t)g32(f.payload+24);event->data.pointer.modifiers=g32(f.payload+28);if(!event->data.pointer.window_id||event->data.pointer.action>PDB_POINTER_ACTION_SCROLL||event->data.pointer.x< -1000000||event->data.pointer.x>1000000||event->data.pointer.y< -1000000||event->data.pointer.y>1000000||(event->data.pointer.buttons&~PDB_POINTER_BUTTON_ALLOWED)!=0u||(event->data.pointer.modifiers&~PDB_MODIFIER_ALLOWED_LOCAL)!=0u){pdb_release_frame(&f);set_error(e,n,"PDB_POINTER_PAYLOAD_INVALID");return-1;}break;case PDB_MSG_KEY_EVENT:if(!cap(c,PDB_CAP_KEYBOARD,e,n)||f.payload_bytes!=PDB_KEY_EVENT_BYTES){pdb_release_frame(&f);set_error(e,n,"PDB_KEY_FRAME_INVALID");return-1;}event->data.key.window_id=g64(f.payload);event->data.key.action=g32(f.payload+8);event->data.key.key_code=g32(f.payload+12);event->data.key.scan_code=g32(f.payload+16);event->data.key.modifiers=g32(f.payload+20);event->data.key.repeat_count=g32(f.payload+24);if(!event->data.key.window_id||event->data.key.action<PDB_KEY_ACTION_DOWN||event->data.key.action>PDB_KEY_ACTION_REPEAT||event->data.key.key_code>0xffff||event->data.key.scan_code>0xffff||(event->data.key.modifiers&~PDB_MODIFIER_ALLOWED_LOCAL)!=0u||event->data.key.repeat_count>10000){pdb_release_frame(&f);set_error(e,n,"PDB_KEY_PAYLOAD_INVALID");return-1;}break;case PDB_MSG_FRAME_PRESENTED:if(!cap(c,PDB_CAP_FRAME_ACK,e,n)||f.payload_bytes!=PDB_FRAME_PRESENTED_BYTES){pdb_release_frame(&f);set_error(e,n,"PDB_FRAME_ACK_INVALID");return-1;}event->data.frame_presented.window_id=g64(f.payload);event->data.frame_presented.frame_id=g64(f.payload+8);event->data.frame_presented.status=g32(f.payload+16);if(!event->data.frame_presented.window_id||event->data.frame_presented.status>16){pdb_release_frame(&f);set_error(e,n,"PDB_FRAME_ACK_PAYLOAD_INVALID");return-1;}break;case PDB_MSG_WINDOW_COMMAND:if(!cap(c,PDB_CAP_WINDOW_SURFACE,e,n)||f.payload_bytes!=PDB_WINDOW_COMMAND_BYTES){pdb_release_frame(&f);set_error(e,n,"PDB_WINDOW_COMMAND_FRAME_INVALID");return-1;}event->data.window_command.window_id=g64(f.payload);event->data.window_command.command=g32(f.payload+8);event->data.window_command.flags=g32(f.payload+12);if(!event->data.window_command.window_id||event->data.window_command.command<PDB_WINDOW_COMMAND_ACTIVATE||event->data.window_command.command>PDB_WINDOW_COMMAND_CLOSE||event->data.window_command.flags!=0u){pdb_release_frame(&f);set_error(e,n,"PDB_WINDOW_COMMAND_PAYLOAD_INVALID");return-1;}break;default:pdb_release_frame(&f);set_error(e,n,"PDB_HOST_EVENT_TYPE_INVALID");return-1;}pdb_release_frame(&f);return 0;}
int pdb_receive_pointer_event(struct pdb_connection*c,struct pdb_pointer_event*v,char*e,size_t n){struct pdb_frame f;if(!v||!cap(c,PDB_CAP_POINTER,e,n)||pdb_receive_frame(c,&f,e,n))return-1;if(f.type!=PDB_MSG_POINTER_EVENT||f.payload_bytes!=PDB_POINTER_EVENT_BYTES){pdb_release_frame(&f);set_error(e,n,"PDB_POINTER_FRAME_INVALID");return-1;}v->window_id=g64(f.payload);v->action=g32(f.payload+8);v->x=(int32_t)g32(f.payload+12);v->y=(int32_t)g32(f.payload+16);v->buttons=g32(f.payload+20);v->vertical_scroll=(int32_t)g32(f.payload+24);v->modifiers=g32(f.payload+28);pdb_release_frame(&f);if(!v->window_id||v->action>PDB_POINTER_ACTION_SCROLL||(v->buttons&~PDB_POINTER_BUTTON_ALLOWED)!=0u||(v->modifiers&~PDB_MODIFIER_ALLOWED_LOCAL)!=0u||v->x< -1000000||v->x>1000000||v->y< -1000000||v->y>1000000){set_error(e,n,"PDB_POINTER_PAYLOAD_INVALID");return-1;}return 0;}
int pdb_receive_key_event(struct pdb_connection*c,struct pdb_key_event*v,char*e,size_t n){struct pdb_frame f;if(!v||!cap(c,PDB_CAP_KEYBOARD,e,n)||pdb_receive_frame(c,&f,e,n))return-1;if(f.type!=PDB_MSG_KEY_EVENT||f.payload_bytes!=PDB_KEY_EVENT_BYTES){pdb_release_frame(&f);set_error(e,n,"PDB_KEY_FRAME_INVALID");return-1;}v->window_id=g64(f.payload);v->action=g32(f.payload+8);v->key_code=g32(f.payload+12);v->scan_code=g32(f.payload+16);v->modifiers=g32(f.payload+20);v->repeat_count=g32(f.payload+24);pdb_release_frame(&f);if(!v->window_id||v->action<PDB_KEY_ACTION_DOWN||v->action>PDB_KEY_ACTION_REPEAT||v->key_code>0xffff||v->scan_code>0xffff||(v->modifiers&~PDB_MODIFIER_ALLOWED_LOCAL)!=0u||v->repeat_count>10000){set_error(e,n,"PDB_KEY_PAYLOAD_INVALID");return-1;}return 0;}
int pdb_receive_frame_presented(struct pdb_connection*c,struct pdb_frame_presented*v,char*e,size_t n){struct pdb_frame f;if(!v||!cap(c,PDB_CAP_FRAME_ACK,e,n)||pdb_receive_frame(c,&f,e,n))return-1;if(f.type!=PDB_MSG_FRAME_PRESENTED||f.payload_bytes!=PDB_FRAME_PRESENTED_BYTES){pdb_release_frame(&f);set_error(e,n,"PDB_FRAME_ACK_INVALID");return-1;}v->window_id=g64(f.payload);v->frame_id=g64(f.payload+8);v->status=g32(f.payload+16);pdb_release_frame(&f);if(!v->window_id||v->status>16){set_error(e,n,"PDB_FRAME_ACK_PAYLOAD_INVALID");return-1;}return 0;}
int pdb_send_window_create(struct pdb_connection*c,uint64_t id,uint64_t parent,uint32_t flags,int32_t w,int32_t h,char*e,size_t n){unsigned char p[28];if(!cap(c,PDB_CAP_WINDOW_SURFACE,e,n)||!id||parent==id||w<=0||w>16384||h<=0||h>16384){if(e&&n&&!e[0])set_error(e,n,"PDB_WINDOW_CREATE_INVALID");return-1;}p64(p,id);p64(p+8,parent);p32(p+16,flags);p32(p+20,(uint32_t)w);p32(p+24,(uint32_t)h);return pdb_send_frame(c,PDB_MSG_WINDOW_CREATE,p,28,e,n);}
int pdb_send_window_geometry(struct pdb_connection*c,uint64_t id,int32_t x,int32_t y,int32_t w,int32_t h,uint32_t vis,uint32_t zflags,uint64_t after,char*e,size_t n){unsigned char p[PDB_WINDOW_GEOMETRY_BYTES];uint32_t zbits=zflags&PDB_ZORDER_ALLOWED;if(!cap(c,PDB_CAP_WINDOW_SURFACE,e,n)||!id||w<=0||w>16384||h<=0||h>16384||x< -1000000||x>1000000||y< -1000000||y>1000000||vis>1||!zflags||zbits!=zflags||(zflags&(zflags-1u))||(zflags==PDB_ZORDER_AFTER_WINDOW?(!after||after==id):after!=0u)){if(e&&n&&!e[0])set_error(e,n,"PDB_WINDOW_GEOMETRY_INVALID");return-1;}p64(p,id);p32(p+8,(uint32_t)x);p32(p+12,(uint32_t)y);p32(p+16,(uint32_t)w);p32(p+20,(uint32_t)h);p32(p+24,vis);p32(p+28,zflags);p64(p+32,after);return pdb_send_frame(c,PDB_MSG_WINDOW_GEOMETRY,p,sizeof(p),e,n);}
int pdb_send_window_destroy(struct pdb_connection*c,uint64_t id,char*e,size_t n){unsigned char p[8];if(!cap(c,PDB_CAP_WINDOW_SURFACE,e,n)||!id){if(e&&n&&!e[0])set_error(e,n,"PDB_WINDOW_ID_INVALID");return-1;}p64(p,id);return pdb_send_frame(c,PDB_MSG_WINDOW_DESTROY,p,8,e,n);}
void pdb_release_frame(struct pdb_frame*f){if(!f)return;free(f->payload);memset(f,0,sizeof(*f));}
void pdb_close(struct pdb_connection*c){invalidate_connection(c);}
